def fecha_en_espanol_final(fecha: date) -> str:
    return f"{DIAS_INICIALES_ES[fecha.weekday()]}, {fecha.day:02d} de {MESES_ES[fecha.month][1].lower()} de {fecha.year}"

def render_fecha_llegada_selector_final(key_prefix: str) -> date:
    hoy = date.today()
    col_year, col_month, col_day = st.columns([1, 1.35, 1], gap="small")
    with col_year:
        year = st.selectbox("Año", list(range(hoy.year - 1, hoy.year + 4)), index=1, key=f"{key_prefix}_fecha_anio")
    with col_month:
        month_label = st.selectbox("Mes", [MESES_ES[i][1] for i in range(1, 13)], index=hoy.month - 1, key=f"{key_prefix}_fecha_mes")
    month = next(i for i, (_, nombre) in MESES_ES.items() if nombre == month_label)
    max_day = calendar.monthrange(year, month)[1]
    with col_day:
        day = st.selectbox(
            "Día",
            list(range(1, max_day + 1)),
            index=min(hoy.day, max_day) - 1,
            format_func=lambda d: f"{DIAS_INICIALES_ES[date(year, month, d).weekday()]} {d:02d}",
            key=f"{key_prefix}_fecha_dia",
        )
    fecha = date(year, month, day)
    st.markdown(f'<div class="calendar-summary">Fecha seleccionada: <strong>{fecha_en_espanol_final(fecha)}</strong></div>', unsafe_allow_html=True)
    return fecha

